/* Google News & Weather __VERSION__ (installed from Play: _aosp/__DEVICE__/playapps/News.apk, not part of the image; see
   docs/sources.md). Generated by docs/tools/news-play.py from docs/templates/news-play.template.js; do not edit.
   NewsActivity (AppThemeLight, the light Toolbar as 5.1.1's News & Weather 2.2 has it: #F5F5F5, the status bar
   #9E9E9E; AppThemeDark under Switch to dark theme): the drawer button, the section's title, menu/news_activity.xml's
   Search and the overflow (Refresh, Edit weather display…, __EDITIONS__, the theme switch). Headlines starts with the
   weather card (weather_large_* of the APK, the temperature and the Temp. / Precip. / Wind / Humidity tabs) whose
   section header menu (menu/section_header.xml) has Edit weather display…, Temperature units… and Wind speed units…;
   each section is a card of stories with "More stories from %1$s". A story opens in WebContentActivity with
   menu/web_content_activity.xml's Open in browser and Share article; Search lists the stories that match or
   "No matching news". The drawer lists the sections, Settings and Help & feedback. The stories are short made-up
   demo pieces (owner decision 2026-10-26), kept offline; the weather is the demo phone's (docs/demo-data.md: Riverside
   18°, partly cloudy). Adding sections, editions, Settings and Help & feedback keep the simulator's limit. */
(() => {
  'use strict';
  const T = () => __NS__.text('news'), t = k => T().t(k);
  const I = name => `assets/__ICONS__-${name}.png`;
  // The demo stories: [section, source, hours ago, title, paragraphs].
  const STORIES = [
    ['Headlines', 'Metro News', 1, 'City opens its new riverside park', ['The long-awaited park along the east bank opened on Saturday with a picnic for the whole neighbourhood.', 'The old warehouse quarter now has a playground, a footbridge and a path that runs all the way to the harbour.']],
    ['Headlines', 'Science Today', 3, 'Researchers map the ocean floor in 3D', ['A survey ship has finished the most detailed map yet of the canyon off the coast, measured to within a metre.', 'The data will help forecast storms and find new places where sea life gathers.']],
    ['Headlines', 'Daily Herald', 5, 'Local bakery wins national bread award', ['A family bakery on Market Street took first place for its sourdough this week.', 'The owners say the secret is patience: each loaf rests for two days before it goes into the oven.']],
    ['Technology', 'Tech Daily', 2, 'Phones learn to answer with a tap', ['The newest messaging apps let you reply from the notification itself, without opening the app.', 'Testers say quick replies save a few seconds every time, and those add up over a day.']],
    ['Technology', 'Gadget Weekly', 6, 'Smart watch batteries now last two days', ['Better chips and dimmer always-on screens mean this year’s watches make it through a weekend.', 'Charging is quicker too: twenty minutes on the dock gives most of a day.']],
    ['Sports', 'Sports Desk', 4, 'Underdogs win the cup final', ['Nobody gave the team from the second division a chance, but a late header settled the final 2–1.', 'Fans filled the town square long after midnight.']],
    ['Sports', 'Metro News', 8, 'Marathon draws a record crowd', ['More than twelve thousand runners started this year’s city marathon under clear skies.', 'Volunteers handed out water at twenty stations along the river route.']],
    ['Headlines', 'Sky Notes', 7, 'A new comet will be visible next month', ['Astronomers expect the comet to be bright enough to see with binoculars in the early evening.', 'Look low in the west just after sunset, away from city lights.']]
  ].map(([section, source, hours, title, body], i) => ({id: 'n' + (i + 1), section, source, hours, title, body}));
  const SECTIONS = ['Headlines', 'Technology', 'Sports'];
  const WEATHER = {temp: 18, high: [17, 19, 21, 22, 21, 19, 17, 15], precip: [0, 0, 10, 20, 10, 0, 0, 0], wind: [8, 10, 13, 15, 14, 11, 9, 8], humidity: [72, 66, 60, 55, 54, 58, 64, 70]};
  const WIND = {mph: v => Math.round(v / 1.609), kmh: v => v, ms: v => Math.round(v / 3.6)};
  const U = c => c.ui.news ||= {section: 'Headlines', drawer: false, search: false, query: '', story: '', tab: 'temp'};
  const S = c => c.data.news ||= {unit: 'C', wind: 'kmh', weather: 'auto', dark: false};
  const refuse = c => c.toast(c.t('This feature is not part of the simulator.'));
  const svg = color => `<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M3 6h18v2H3zm0 5h18v2H3zm0 5h18v2H3z" fill="${color}"/></svg>`;
  const label = (c, id) => id === 'Headlines' ? t('headlines_section_title') : c.t(id);
  const ago = (c, h) => new Intl.RelativeTimeFormat(c.locale(), {numeric: 'auto'}).format(-h, 'hour');
  const deg = (c, v) => S(c).unit === 'F' ? Math.round(v * 9 / 5 + 32) : v;
  const row = (c, s) => `<button type="button" class="__CLS__-story" data-action="__CLS__-open" data-id="${s.id}"><span><b>${c.safe(s.title)}</b><small>${c.safe(s.source)} · ${c.safe(ago(c, s.hours))}</small></span><i class="__CLS__-thumb" style="--h:${(Number(s.id.slice(1)) * 47) % 360}"></i></button>`;
  function weather(c) {
    const s = S(c), u = U(c), dark = s.dark;
    if (s.weather === 'hide') return '';
    const tabs = [['temp', 'weather_tab_temperature'], ['precip', 'weather_tab_precipitation'], ['wind', 'weather_tab_wind'], ['humidity', 'weather_tab_humidity']];
    const values = u.tab === 'temp' ? WEATHER.high.map(v => deg(c, v)) : u.tab === 'wind' ? WEATHER.wind.map(WIND[s.wind]) : WEATHER[u.tab];
    const max = Math.max(...values, 1);
    return `<section class="__CLS__-card"><header class="__CLS__-head"><h3>${c.safe(label(c, 'Headlines'))}</h3><button type="button" class="__CLS__-hmenu" data-action="__CLS__-hmenu" aria-label="${c.safe(t('section_header_menu_description'))}"><img src="${I('ic_more_horiz_white_18dp')}" alt=""></button></header>
      <div class="__CLS__-now"><img src="${I('weather_large_partly_cloudy')}" alt=""><b>${deg(c, WEATHER.temp)}°</b><span><button type="button" data-action="__CLS__-unit" data-id="C" class="${s.unit === 'C' ? 'on' : ''}">${c.safe(t('weather_unit_switcher_celsius'))}</button> | <button type="button" data-action="__CLS__-unit" data-id="F" class="${s.unit === 'F' ? 'on' : ''}">${c.safe(t('weather_unit_switcher_fahrenheit'))}</button></span><small>Riverside · ${c.safe(t('weather_condition_partly_cloudy'))}</small></div>
      <div class="__CLS__-tabs">${tabs.map(([id, key]) => `<button type="button" class="${u.tab === id ? 'on' : ''}" data-action="__CLS__-tab" data-id="${id}">${c.safe(t(key))}</button>`).join('')}</div>
      <div class="__CLS__-chart${dark ? ' dark' : ''}">${values.map((v, i) => `<span><small>${u.tab === 'precip' ? c.safe(AndroidStrings.format(t('weather_chart_precipitation_format'), v)) : u.tab === 'humidity' ? v + '%' : v}</small><i style="height:${Math.max(4, v / max * 100)}%"></i><em>${String((6 + i * 3) % 24).padStart(2, '0')}</em></span>`).join('')}</div></section>`;
  }
  function section(c, id) {
    const list = STORIES.filter(s => s.section === id);
    const head = id === 'Headlines' && S(c).weather !== 'hide' ? '' : `<header class="__CLS__-head"><h3>${c.safe(label(c, id))}</h3></header>`;
    return `<section class="__CLS__-card">${head}${list.map(s => row(c, s)).join('')}<footer class="__CLS__-foot">${c.safe(AndroidStrings.format(t('section_footer_format'), list[0]?.source || ''))}</footer></section>`;
  }
  function web(c, s) {
    return `<div class="__CLS__${S(c).dark ? ' dark' : ''}"><header class="__CLS__-bar"><button type="button" class="__CLS__-btn" data-action="__CLS__-close" aria-label="${c.safe(t('navigate_up_content_description'))}"><img src="${I('ic_arrow_back_white_24dp')}" alt="" class="__CLS__-tint"></button><b>${c.safe(s.source)}</b>${__NS__.menu.button(c, '__CLS__-more', !S(c).dark)}</header><article class="__CLS__-article"><h1>${c.safe(s.title)}</h1><p class="__CLS__-by">${c.safe(s.source)} · ${c.safe(ago(c, s.hours))}</p>${s.body.map(p => `<p>${c.safe(p)}</p>`).join('')}</article></div>`;
  }
  function render(c) {
    const u = U(c), s = S(c), story = u.story && STORIES.find(x => x.id === u.story);
    if (story) return web(c, story);
    const q = u.query.trim().toLocaleLowerCase(), found = q ? STORIES.filter(x => (x.title + ' ' + x.source).toLocaleLowerCase().includes(q)) : [];
    const bar = u.search
      ? `<header class="__CLS__-bar"><button type="button" class="__CLS__-btn" data-action="__CLS__-search-close" aria-label="${c.safe(t('navigate_up_content_description'))}"><img src="${I('ic_arrow_back_white_24dp')}" alt="" class="__CLS__-tint"></button><input class="__CLS__-query" data-news-search value="${c.safe(u.query)}" placeholder="${c.safe(t('search_hint'))}" aria-label="${c.safe(t('menu_search'))}" autocomplete="off" spellcheck="false"></header>`
      : `<header class="__CLS__-bar"><button type="button" class="__CLS__-btn" data-action="__CLS__-drawer" aria-label="${c.safe(t('drawer_open'))}">${svg(s.dark ? '#fff' : '#000000de')}</button><b>${c.safe(label(c, u.section))}</b><button type="button" class="__CLS__-btn" data-action="__CLS__-search" aria-label="${c.safe(t('menu_search'))}"><img src="${I('abc_ic_search_api_mtrl_alpha')}" alt="" class="__CLS__-tint"></button>${__NS__.menu.button(c, '__CLS__-more', !s.dark)}</header>`;
    const body = u.search ? (q ? (found.length ? `<section class="__CLS__-card">${found.map(x => row(c, x)).join('')}</section>` : `<p class="__CLS__-empty">${c.safe(t('content_loading_empty_state'))}</p>`) : '')
      : (u.section === 'Headlines' ? weather(c) : '') + section(c, u.section);
    const drawer = u.drawer ? `<div class="__CLS__-scrim" data-action="__CLS__-drawer"></div><nav class="__CLS__-drawer"><div class="__CLS__-account"><small>${c.safe(__NS__.account?.email || '')}</small></div>${SECTIONS.map(id => `<button type="button" class="${u.section === id ? 'on' : ''}" data-action="__CLS__-section" data-id="${id}">${c.safe(label(c, id))}</button>`).join('')}<hr><button type="button" data-action="__CLS__-unavailable">${c.safe(t('drawer_link_settings'))}</button><button type="button" data-action="__CLS__-unavailable">${c.safe(t('drawer_link_help'))}</button></nav>` : '';
    return `<div class="__CLS__${s.dark ? ' dark' : ''}">${bar}<div class="__CLS__-scroll">${body}</div>${drawer}</div>`;
  }
  function mount(c, root) {
    const u = U(c), q = root.querySelector('[data-news-search]');
    if (q) { q.addEventListener('input', () => { u.query = q.value; const at = q.selectionStart; c.render(); const n = c.el.viewport.querySelector('[data-news-search]'); if (n) { n.focus(); n.setSelectionRange(at, at); } }); if (u.focus) { u.focus = false; requestAnimationFrame(() => q.focus()); } }
  }
  const choose = (c, title, options, current, set) => c.dialog({title, items: options.map(([id, text]) => ({html: `<span class="__CLS__-radio${current === id ? ' on' : ''}"></span>${c.safe(text)}`})), onItem: (i, c) => { set(options[i][0]); c.save(); c.render(); }});
  const weatherDialog = c => choose(c, t('default_location_dialog_title'), [['hide', t('default_location_dialog_hide_text')], ['auto', t('default_location_dialog_auto_text')], ['custom', t('default_location_dialog_custom_text')]], S(c).weather, v => { if (v === 'custom') refuse(c); else S(c).weather = v; });
  function action(name, el, ev, c) {
    const u = U(c), s = S(c);
    if (name === '__NS_LOWER__-menu') {
      const story = u.story && STORIES.find(x => x.id === u.story);
      if (story) c.menu([{label: t('menu_open_in_browser'), action: refuse}, {label: t('story_share_title'), action: c => __NS__.share(c, {title: t('story_share_title'), subject: story.title, text: `${story.title}\n${story.source}`})}], el);
      else c.menu([{label: t('menu_refresh'), action: c => c.render()}, {label: t('menu_edit_weather_location'), action: weatherDialog}, {label: t('menu_change_editions'), action: refuse},
        {label: t(s.dark ? 'menu_switch_theme_light' : 'menu_switch_theme_dark'), action: c => { s.dark = !s.dark; c.save(); c.render(); }}], el);
      return true;
    }
    if (!name.startsWith('__CLS__-')) return false;
    switch (name.slice('__CLS__-'.length)) {
      case 'drawer': u.drawer = !u.drawer; break;
      case 'section': Object.assign(u, {section: el.dataset.id, drawer: false}); break;
      case 'search': Object.assign(u, {search: true, query: '', focus: true}); break;
      case 'search-close': Object.assign(u, {search: false, query: ''}); break;
      case 'open': u.story = el.dataset.id; break;
      case 'close': u.story = ''; break;
      case 'tab': u.tab = el.dataset.id; break;
      case 'unit': s.unit = el.dataset.id; c.save(); break;
      case 'hmenu': c.menu([{label: t('menu_edit_weather_location'), action: weatherDialog},
        {label: t('menu_temperature_units'), action: c => choose(c, t('pref_temperature_units'), [['C', t('weather_unit_switcher_celsius')], ['F', t('weather_unit_switcher_fahrenheit')]], s.unit, v => { s.unit = v; })},
        {label: t('menu_wind_speed_units'), action: c => choose(c, t('pref_wind_speed_units'), [['mph', t('speed_units_mph')], ['kmh', t('speed_units_kmh')], ['ms', t('speed_units_ms')]], s.wind, v => { s.wind = v; })}], el); return true;
      case 'unavailable': u.drawer = false; c.render(); refuse(c); return true;
      default: return false;
    }
    c.render(); return true;
  }
  __NS__.register('news-weather', {
    render, mount, action,
    statusColor: c => S(c).dark ? '#000000' : '#9e9e9e',
    back(c) {
      const u = U(c);
      if (u.story) { u.story = ''; c.render(); return true; }
      if (u.drawer) { u.drawer = false; c.render(); return true; }
      if (u.search) { Object.assign(u, {search: false, query: ''}); c.render(); return true; }
      if (u.section !== 'Headlines') { u.section = 'Headlines'; c.render(); return true; }
      return false;
    }
  });
})();
